import { View, Text } from 'react-native';
import tw from 'twrnc';


const Reviews = () => {
 
'/bookReviews/:bookId'
  return (
    <View style={tw`p-4`}>
      <Text style={[tw`text-lg`]}>Reviews:</Text>
    
    </View>
  );
};

